-- Transfer 2500 cents from acct-a to acct-b as one atomic unit.
BEGIN;

SET TRANSACTION ISOLATION LEVEL READ COMMITTED;

-- Lock both rows in a stable order before reading their balances.
SELECT balance_cents
FROM accounts
WHERE id = 'acct-a'
FOR UPDATE;

SELECT balance_cents
FROM accounts
WHERE id = 'acct-b'
FOR UPDATE;

UPDATE accounts
SET balance_cents = balance_cents - 2500
WHERE id = 'acct-a' AND balance_cents >= 2500;

UPDATE accounts
SET balance_cents = balance_cents + 2500
WHERE id = 'acct-b';

-- The application checks the debit row count before this point.
-- READ COMMITTED waits on the row lock. REPEATABLE READ would abort a
-- conflicting write instead, so the application would need a retry loop.
COMMIT;

-- A transfer rejected by its balance guard is rolled back as a unit.
BEGIN;

SET TRANSACTION ISOLATION LEVEL READ COMMITTED;

SELECT balance_cents
FROM accounts
WHERE id = 'acct-a'
FOR UPDATE;

UPDATE accounts
SET balance_cents = balance_cents - 2500
WHERE id = 'acct-a' AND balance_cents >= 2500;

-- The guard matched zero rows in this run, so the transfer is abandoned.
ROLLBACK;
